\begin{document}
\maketitle

\begin{abstract}
The Berggren tree is the free rooted ternary tree whose nodes enumerate the primitive
Pythagorean triples exactly once, generated from the seed $(m,n)=(2,1)$ by the three
Euclid-seed moves $L(m,n)=(2m-n,m)$, $M(m,n)=(2m+n,m)$, $R(m,n)=(m+2n,n)$. We develop the
complete probabilistic and ergodic theory of the random walk on this tree that selects the
three moves independently with fixed probabilities $(p_L,p_M,p_R)$.

We show that the boundary of the tree is a Cantor space, canonically identified with
$\{0,1,2\}^{\N}$ under the 3-adic (common-prefix) topology. We prove that the harmonic
measure of the walk \emph{exists and is unique}, and equals the Bernoulli product measure;
the fair walk realises the natural Cantor measure. We compute its entropy exactly: the mean
surprisal of a depth-$n$ node is $nH(P)$ with no error term, and
$-\tfrac1n\log\nu(\cyl_n(x))\to H(P)$ almost surely, whence the pointwise dimension is
$H(P)/\log 3\le 1$ with equality iff the walk is fair.

We prove that the boundary shift is ergodic for every harmonic measure, that distinct walks
yield mutually singular harmonic measures, and that this singularity is rigid: an
everywhere-defined frequency statistic recovers the weight vector from a single typical ray,
and ``equal versus mutually singular'' is a strict dichotomy. Quantitatively, distinct walks
are separated already at depth $n$ at the binary Kullback--Leibler rate, and this cannot be
improved beyond the Bhattacharyya exponent: for every event $A$ of the first $n$ letters,
$\nu_P(A)+\nu_Q(A^c)\ge\tfrac12\beta^{2n}$ with $\beta=\sum_a\sqrt{p_aq_a}$.

Finally we connect the probabilistic theory to the hyperbolic geometry of the tree. Averaging
the sharp deterministic envelope $(\#M(w)+1)\log 2\le d\le(|w|+1)\log(1+\sqrt2)+\log 2$ over
the walk gives the drift sandwich $p_M\log2\le\E\,d(o,z_n)/n\le\log(1+\sqrt2)+O(1/n)$,
upgraded almost surely by the strong law; in particular the walk escapes to infinity almost
surely. Two negative results complete the picture: the transfer operator restricted to
locally constant observables is nilpotent modulo constants, so its spectrum is $\{0,1\}$ and
the spectral gap is $1$ independently of the weights, refuting the conjecture that the silver
ratio governs the gap; and $\log3<2\log(1+\sqrt2)$, so the hyperbolic dimension
$H(P)/(2\log(1+\sqrt2))$ of the harmonic measure is bounded by $2/3$ uniformly.
\end{abstract}

\medskip
\noindent\textbf{Keywords:} Pythagorean triples, Berggren tree, harmonic measure, Bernoulli
measure, Cantor set, Shannon entropy, Hausdorff dimension, silver ratio, Chernoff bound,
Bhattacharyya coefficient.

\section{Introduction}

\subsection{The Berggren tree}

Euclid's parametrisation of the primitive Pythagorean triples is a bijection between the set
\[
\mathcal{S}=\{(m,n)\in\Z^2 : m>n>0,\ \gcd(m,n)=1,\ m\not\equiv n \bmod 2\}
\]
of \emph{seeds} and the set of primitive triples, via $(m,n)\mapsto(m^2-n^2,\,2mn,\,m^2+n^2)$.
Berggren's theorem states that $\mathcal S$ carries the structure of a free rooted ternary
tree: the root is $(2,1)$ --- the seed of $(3,4,5)$ --- and the three maps
\[
L(m,n)=(2m-n,\,m),\qquad M(m,n)=(2m+n,\,m),\qquad R(m,n)=(m+2n,\,n)
\]
carry $\mathcal S$ into itself and realise every seed other than $(2,1)$ exactly once. Thus
the map $\mathrm{run}$ from finite words in $\{L,M,R\}$ to seeds, defined by
$\mathrm{run}(\varepsilon)=(2,1)$ and $\mathrm{run}(aw)=a(\mathrm{run}(w))$, is a bijection:
the primitive Pythagorean triples are canonically indexed by the free monoid on three
generators.

The three moves are not symmetric. In the metric picture (Section~\ref{sec:drift}) the
\emph{middle} move $M$ is distinguished: it is the unique one saturating the growth of the
potential $\Phi(m,n)=m+(\sqrt2-1)n$, whose growth constant is the silver ratio $1+\sqrt2$.

\subsection{The boundary and the walk}

Since the tree is free and ternary, its space of ends is the full three-letter shift space.
Write $\A=\{0,1,2\}$ with $0\leftrightarrow L$, $1\leftrightarrow M$, $2\leftrightarrow R$, and
$\bdry=\A^{\N}$, with the product topology of discrete topologies and the product
$\sigma$-algebra.

Fix a \emph{weight vector} $P=(p_0,p_1,p_2)$ with $p_a>0$ and $\sum_a p_a=1$. The
\emph{Berggren random walk} with weights $P$ starts at the root and at each step appends the
letter $a$ with probability $p_a$, independently of the past. It converges to a boundary
point; the law of the limit is the \emph{harmonic measure} of the walk. Throughout, $\log$ is
the natural logarithm and $H(P)=-\sum_a p_a\log p_a$ is Shannon entropy in nats.

\section{The boundary is a Cantor set}

\begin{definition}[Cylinders]
For $n\in\N$ and $v\in\bdry$ put $\cyl_n(v)=\{x\in\bdry: x_i=v_i \text{ for all } i<n\}$.
Equivalently, $\cyl_n(v)$ is the \emph{shadow} of the node
$\mathrm{run}(v_0v_1\cdots v_{n-1})$ --- the set of ends passing through that primitive
Pythagorean triple. In particular $\cyl_0(v)=\bdry$.
\end{definition}

\begin{lemma}[Nesting]\label{lem:nest}
If $x\in\cyl_n(v)\cap\cyl_m(w)$ with $n\le m$, then $\cyl_m(w)\subseteq\cyl_n(v)$.
\end{lemma}

\begin{proof}
For $i<n\le m$ and $y\in\cyl_m(w)$ we have $y_i=w_i=x_i=v_i$.
\end{proof}

Hence the cylinders form a $\pi$-system: the intersection of two cylinders is empty or equal
to the deeper one. They also generate the product $\sigma$-algebra, since the event
$\{x_i=a\}$ is a finite union of depth-$(i+1)$ cylinders.

\begin{proposition}[Cylinders determine measures]\label{prop:ext}
Two probability measures on $\bdry$ agreeing on every cylinder are equal.
\end{proposition}

\begin{proof}
Dynkin's $\pi$--$\lambda$ theorem applied to the generating $\pi$-system of cylinders, using
that both measures have total mass $1$.
\end{proof}

\begin{theorem}[Cantor structure of the boundary]\label{thm:cantor}
The boundary $\bdry$, with the common-prefix topology, is nonempty, compact, second countable
and metrizable (a compatible metric is $d(x,y)=3^{-\min\{i:\,x_i\ne y_i\}}$), totally
disconnected, and perfect. Moreover the cylinders are clopen and form a neighbourhood basis
at every point, and every cylinder contains at least two distinct points, so every subtree of
the Berggren tree branches forever.
\end{theorem}

\begin{proof}
Compactness is Tychonoff; second countability and metrizability are standard for countable
products of finite discrete spaces. Each $\cyl_n(v)$ is a finite intersection of preimages of
points under continuous maps into discrete spaces, hence clopen, which gives total
disconnectedness. A basic product neighbourhood constrains finitely many coordinates, all of
index at most some $N$, so $\cyl_{N+1}(x)$ is contained in it, giving the basis statement. For
perfectness, let $x^{(k)}$ be $x$ with its $k$-th letter incremented cyclically; then
$x^{(k)}\ne x$, while $x^{(k)}_i=x_i$ whenever $k>i$, so $x^{(k)}\to x$. Taking $k=n$ gives a
second point of $\cyl_n(x)$.
\end{proof}

By Brouwer's characterisation of the Cantor set, $\bdry$ is homeomorphic to the classical
middle-thirds Cantor set.

\section{The harmonic measure}

Let $\cons_a:\bdry\to\bdry$ prepend the letter $a$: $(\cons_a x)_0=a$ and
$(\cons_a x)_{k+1}=x_k$. Geometrically $\cons_a$ identifies the whole boundary with the shadow
of the $a$-child of the root.

\begin{definition}[Harmonic measure]
A Borel probability measure $\nu$ on $\bdry$ is \emph{harmonic} (stationary, self-similar) for
$P$ if
\[
\nu=\sum_{a\in\A}p_a\,(\cons_a)_*\nu,
\qquad\text{i.e.}\qquad
\nu(S)=\sum_a p_a\,\nu(\cons_a^{-1}S)\ \text{ for all measurable } S.
\]
\end{definition}

This says exactly that the hitting distribution is reproduced by conditioning on the first
step: the boundary decomposes into the three shadows of the children of the root, the walk
enters the $a$-shadow with probability $p_a$, and conditionally it is again a copy of itself.

\begin{definition}
$\Ber(P)$ is the infinite product measure $\bigotimes_{i\in\N}\mu_P$ on $\bdry$, where
$\mu_P(\{a\})=p_a$.
\end{definition}

\begin{lemma}[Cylinder mass]\label{lem:cylmass}
$\Ber(P)(\cyl_n(v))=\prod_{i<n}p_{v_i}$.
\end{lemma}

\begin{proof}
$\cyl_n(v)$ is the measurable box $\prod_{i<n}\{v_i\}\times\prod_{i\ge n}\A$.
\end{proof}

\begin{lemma}[Pullback of a cylinder]\label{lem:pullback}
For $a\in\A$, $n\in\N$, $v\in\bdry$,
\[
\cons_a^{-1}\bigl(\cyl_{n+1}(v)\bigr)=
\begin{cases}\cyl_n(\sigma v)&\text{if } a=v_0,\\ \varnothing&\text{otherwise,}\end{cases}
\]
where $\sigma v=(v_1,v_2,\dots)$.
\end{lemma}

\begin{proof}
$\cons_a x\in\cyl_{n+1}(v)$ requires $a=v_0$ and $x_k=v_{k+1}$ for $k<n$.
\end{proof}

\begin{theorem}[Existence and uniqueness of the harmonic measure]\label{thm:main}
For every strictly positive weight vector $P$ there is exactly one harmonic probability
measure on the boundary of the Berggren tree, namely $\Ber(P)$. A probability measure $\nu$ is
harmonic for $P$ if and only if $\nu=\Ber(P)$, and then
$\nu(\cyl_n(v))=\prod_{i<n}p_{v_i}$.
\end{theorem}

\begin{proof}
\emph{Uniqueness of cylinder masses.} Let $\nu$ be harmonic. We prove
$\nu(\cyl_n(v))=\prod_{i<n}p_{v_i}$ by induction on $n$. For $n=0$ both sides are $1$. For
$n+1$, apply harmonicity to $\cyl_{n+1}(v)$ and use Lemma~\ref{lem:pullback}: all terms with
$a\ne v_0$ vanish, and the surviving term is
$p_{v_0}\nu(\cyl_n(\sigma v))=p_{v_0}\prod_{i<n}p_{(\sigma v)_i}=\prod_{i<n+1}p_{v_i}$.

\emph{Harmonicity of $\Ber(P)$.} Put $\nu'=\sum_a p_a(\cons_a)_*\Ber(P)$. Evaluating at
$\bdry$ gives $\nu'(\bdry)=\sum_a p_a=1$, so $\nu'$ is a probability measure; the same
recursion, now using Lemma~\ref{lem:cylmass}, gives $\nu'(\cyl_n(v))=\prod_{i<n}p_{v_i}$ for
every cylinder, so $\nu'=\Ber(P)$ by Proposition~\ref{prop:ext}.

Combining the two paragraphs with Proposition~\ref{prop:ext} gives the equivalence.
\end{proof}

\begin{corollary}[Fair walk sees the Cantor measure]
For $p_0=p_1=p_2=1/3$ one has $\Ber(P)(\cyl_n(v))=3^{-n}$: the harmonic measure of the fair
walk is the natural Hausdorff/Cantor measure of the 3-adic boundary.
\end{corollary}

\begin{corollary}[Full support]\label{cor:support}
Every cylinder has strictly positive harmonic mass, hence so does every nonempty open set: all
harmonic measures have full support.
\end{corollary}

\section{Entropy and dimension}

\begin{definition}
The \emph{surprisal} of a move is $\iota(a)=-\log p_a\ge0$, and
$H(P)=\sum_a p_a\iota(a)=-\sum_a p_a\log p_a$.
\end{definition}

\begin{proposition}[Gibbs]\label{prop:gibbs}
$0\le H(P)\le\log3$, with $H(P)=\log3$ iff $p_a=1/3$ for all $a$.
\end{proposition}

\begin{proof}
Nonnegativity is termwise. Apply $\log t\le t-1$ (strict unless $t=1$) with $t=1/(3p_a)$:
$p_a\log\frac{1}{3p_a}\le \frac13-p_a$. Summing, the left side is $-\log3+H(P)$ and the right
side is $0$. If some $p_a\ne1/3$ the corresponding inequality is strict.
\end{proof}

\begin{theorem}[Mean surprisal of a depth-$n$ node]\label{thm:exact}
For every $n$,
\[
\sum_{w\in\A^n}\Bigl(\prod_{i<n}p_{w_i}\Bigr)\Bigl(-\log\prod_{i<n}p_{w_i}\Bigr)=n\,H(P).
\]
Summing over all $3^n$ primitive Pythagorean triples at depth $n$, weighted by harmonic mass,
the average information content of a depth-$n$ node is exactly $nH(P)$: an identity, not an
asymptotic.
\end{theorem}

\begin{proof}
Write $-\log\prod_ip_{w_i}=\sum_{i<n}\iota(w_i)$ and exchange the order of summation. For
fixed $i$, factor the inner sum over $w_i$ and the remaining coordinates; the latter sum to
$1$, leaving $\sum_a p_a\iota(a)=H(P)$. There are $n$ values of $i$.
\end{proof}

\begin{theorem}[Strong law for the letters]\label{thm:slln}
For every $g:\A\to\R$ and $\Ber(P)$-a.e.\ $x$,
$\frac1n\sum_{i<n}g(x_i)\to\sum_a p_ag(a)$.
\end{theorem}

\begin{proof}
The coordinates are i.i.d.\ with law $\mu_P$ under the product measure; apply Kolmogorov's
strong law to the bounded observables $x\mapsto g(x_i)$.
\end{proof}

\begin{theorem}[Shannon--McMillan--Breiman on the Berggren boundary]\label{thm:smb}
For $\Ber(P)$-a.e.\ $x$, $-\tfrac1n\log\Ber(P)(\cyl_n(x))\to H(P)$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:cylmass}, $-\log\Ber(P)(\cyl_n(x))=\sum_{i<n}\iota(x_i)$; apply
Theorem~\ref{thm:slln} with $g=\iota$, whose mean is $H(P)$.
\end{proof}

Since $\diam\cyl_n(x)=3^{-n}$ in the metric of Theorem~\ref{thm:cantor}, the pointwise
(Billingsley) dimension of $\nu$ at $x$ is $\lim_n \log\nu(\cyl_n(x))/\log 3^{-n}$.

\begin{theorem}[Pointwise dimension]\label{thm:dim}
Set $\dim\nu_P=H(P)/\log3$. For $\Ber(P)$-a.e.\ $x$,
\[
\frac{\log\Ber(P)(\cyl_n(x))}{\log 3^{-n}}\longrightarrow\frac{H(P)}{\log3}.
\]
Consequently $\dim\nu_P\in[0,1]$; $\dim\nu_P=1$ iff $p_0=p_1=p_2=1/3$; and if any $p_a\ne1/3$
then $\dim\nu_P<1$ strictly.
\end{theorem}

\begin{proof}
Divide Theorem~\ref{thm:smb} by $\log3$, using $\log3^{-n}=-n\log3$; the range and rigidity
statements are Proposition~\ref{prop:gibbs} divided by $\log3$.
\end{proof}

Thus the fair walk spreads over the whole boundary and every biased walk concentrates on a
fractal subset of strictly smaller dimension, the loss being exactly the Gibbs deficit.

\section{Ergodic theory and separation}

\subsection{Ergodicity}

Let $\sigma:\bdry\to\bdry$, $(\sigma x)_k=x_{k+1}$, be the shift ``forget the first Berggren
move''.

\begin{proposition}[Stationarity]
$\sigma$ preserves $\Ber(P)$.
\end{proposition}

\begin{proof}
$\sigma^{-1}\cyl_n(v)=\bigsqcup_{a\in\A}\cyl_{n+1}(av)$, of mass
$\bigl(\sum_a p_a\bigr)\prod_{i<n}p_{v_i}=\prod_{i<n}p_{v_i}$; conclude by
Proposition~\ref{prop:ext}.
\end{proof}

\begin{theorem}[Ergodicity]\label{thm:erg}
For every $P$ the shift $\sigma$ is ergodic for $\Ber(P)$. Hence every shift-invariant
boundary observable is a.s.\ constant, and $\Ber(P)$ is an extreme point of the simplex of
$\sigma$-invariant probability measures on the boundary.
\end{theorem}

\begin{proof}
The coordinate $\sigma$-algebras are independent under the product measure. A strictly
invariant set $S$ satisfies $S=(\sigma^n)^{-1}S$ for all $n$, and $\sigma^n$ reads only
coordinates $\ge n$, so $S$ lies in the tail $\sigma$-algebra; Kolmogorov's $0$--$1$ law gives
$\Ber(P)(S)\in\{0,1\}$.
\end{proof}

\subsection{Mutual singularity and ray rigidity}

\begin{definition}[Frequency statistic]
For $a\in\A$ define on \emph{all} of $\bdry$
\[
\rho_a(x)=\limsup_{n\to\infty}\frac1n\#\{i<n : x_i=a\},
\qquad \rho(x)=(\rho_0(x),\rho_1(x),\rho_2(x)).
\]
$\rho$ is Borel and defined everywhere. Call $x$ \emph{typical for $P$} if the empirical
frequency of each letter $a$ converges to $p_a$, and write $\Typ(P)$ for the set of such rays.
\end{definition}

By Theorem~\ref{thm:slln} applied to indicators, $\Ber(P)(\Typ(P))=1$; in particular $\Typ(P)$
is nonempty and $\rho(x)=P$ for $x\in\Typ(P)$.

\begin{theorem}[Ray rigidity]\label{thm:rigid}
For weight vectors $P,Q$ the following are equivalent:
\begin{enumerate}
\item $P=Q$;
\item $\Typ(P)\cap\Typ(Q)\ne\varnothing$, i.e.\ some single ray is typical for both walks;
\item $\Ber(P)=\Ber(Q)$;
\item $\Ber(P)$ and $\Ber(Q)$ are \emph{not} mutually singular.
\end{enumerate}
In particular distinct walks have disjoint sets of typical rays and mutually singular harmonic
measures; $P\mapsto\Ber(P)$ is injective; and there is no regime between ``identical'' and
``maximally different''.
\end{theorem}

\begin{proof}
$(1)\Rightarrow(2)$: $\Typ(P)=\Typ(Q)\ne\varnothing$. $(2)\Rightarrow(1)$: if $x$ is typical
for both then $P=\rho(x)=Q$. $(1)\Rightarrow(3)$: identical one-step laws give identical
product measures. $(3)\Rightarrow(4)$: a probability measure is never mutually singular with
itself. $(4)\Rightarrow(1)$, contrapositive: if $P\ne Q$ then $\Typ(P)$ carries all the mass of
$\Ber(P)$ and none of that of $\Ber(Q)$, since $\Typ(Q)$ is $\Ber(Q)$-conull and disjoint from
$\Typ(P)$.
\end{proof}

\begin{remark}
Contrast with Corollary~\ref{cor:support}: all harmonic measures have full support and charge
exactly the same open sets, yet they are pairwise mutually singular. Singularity here is a
purely asymptotic phenomenon, invisible at any finite depth.
\end{remark}

\subsection{Quantitative separation: the Chernoff rate}

\begin{definition}
The binary relative entropy is
$\KL(u\Vert s)=u\log\frac us+(1-u)\log\frac{1-u}{1-s}$ for $u,s\in(0,1)$; it is strictly
positive whenever $u\ne s$.
\end{definition}

\begin{lemma}[Exact factorisation of the moment generating function]\label{lem:mgf}
For $g:\A\to\R$ and $S_n(x)=\sum_{i<n}g(x_i)$,
$\E_{\Ber(P)}[e^{tS_n}]=\bigl(\sum_a p_ae^{tg(a)}\bigr)^n$.
\end{lemma}

\begin{theorem}[Chernoff bounds for letter counts]\label{thm:chernoff}
Let $N^{(n)}_a(x)=\#\{i<n:x_i=a\}$. For $p_a<u<1$,
\[
\Ber(P)\bigl[N^{(n)}_a\ge nu\bigr]\le e^{-n\KL(u\Vert p_a)},
\]
and for $0<u<p_a$, $\Ber(P)\bigl[N^{(n)}_a\le nu\bigr]\le e^{-n\KL(u\Vert p_a)}$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply the exponential Markov inequality to $g=\mathbf 1_a$ at the classical tilt
$t=\log\frac{u(1-p_a)}{p_a(1-u)}>0$. Lemma~\ref{lem:mgf} makes the moment generating function
exactly $(1-p_a+p_ae^t)^n$, and substituting the optimal $t$ turns
$e^{-tnu}(1-p_a+p_ae^t)^n$ into $e^{-n\KL(u\Vert p_a)}$. The lower tail follows from the upper
tail applied to $1-\mathbf 1_a$ together with $\KL(1-u\Vert1-s)=\KL(u\Vert s)$.
\end{proof}

\begin{theorem}[Exponential separation at depth $n$]\label{thm:sep}
If $P\ne Q$ there are $c>0$ and sets $A_n$, each determined by the first $n$ letters, with
\[
\Ber(P)(A_n)\ge1-e^{-cn},\qquad \Ber(Q)(A_n)\le e^{-cn}\qquad (n\in\N).
\]
Consequently $\Ber(P)(A_n)-\Ber(Q)(A_n)\to1$: mutual singularity is the $n\to\infty$ shadow of
an exponential cutoff.
\end{theorem}

\begin{proof}
Pick $a$ with $q_a<p_a$ (else complement) and $u$ strictly between them; take
$A_n=\{N^{(n)}_a\ge nu\}$ and apply Theorem~\ref{thm:chernoff} with
$c=\min\{\KL(u\Vert p_a),\KL(u\Vert q_a)\}>0$.
\end{proof}

\subsection{The converse: a Bhattacharyya speed limit}

\begin{definition}
The Bhattacharyya coefficient is $\beta(P,Q)=\sum_{a\in\A}\sqrt{p_aq_a}$.
\end{definition}

\begin{lemma}\label{lem:beta}
$0<\beta(P,Q)\le1$, with $\beta(P,Q)<1$ iff $P\ne Q$.
\end{lemma}

\begin{proof}
AM--GM gives $\sqrt{p_aq_a}\le(p_a+q_a)/2$ with equality iff $p_a=q_a$; sum and use
$\sum_a(p_a+q_a)/2=1$.
\end{proof}

\begin{lemma}[Factorisation of the depth-$n$ affinity]\label{lem:affinity}
With $m_P(w)=\prod_{i<n}p_{w_i}$ the harmonic mass of the node labelled by $w\in\A^n$,
$\sum_{w\in\A^n}\sqrt{m_P(w)m_Q(w)}=\beta(P,Q)^n$.
\end{lemma}

\begin{theorem}[No test beats the Bhattacharyya exponent]\label{thm:bhatt}
Let $A$ be any event determined by the first $n$ letters. Then
\[
\Ber(P)(A)+\Ber(Q)(A^c)\;\ge\;\tfrac12\,\beta(P,Q)^{2n}.
\]
Hence the exponential rate at which any depth-$n$ test can separate two Berggren walks is at
most $-2\log\beta(P,Q)$; with Theorem~\ref{thm:sep} this brackets the true cutoff rate.
\end{theorem}

\begin{proof}
Write $A=\bigcup_{w\in W}\cyl_n(w)$. Then
$\Ber(P)(A)+\Ber(Q)(A^c)=\sum_{w\in W}m_P(w)+\sum_{w\notin W}m_Q(w)\ge\sum_{w}\min(m_P,m_Q)(w)$.
With $m=\min(m_P,m_Q)$ and $M=\max(m_P,m_Q)$ we have $mM=m_Pm_Q$ and $M\le m_P+m_Q$, so by
Cauchy--Schwarz and Lemma~\ref{lem:affinity}
\[
\beta^{2n}=\Bigl(\sum_w\sqrt m\sqrt M\Bigr)^{2}
\le\Bigl(\sum_w m\Bigr)\Bigl(\sum_w M\Bigr)\le 2\sum_w m ,
\]
using $\sum_w m_P=\sum_w m_Q=1$. Rearranging gives $\sum_w m\ge\tfrac12\beta^{2n}$.
\end{proof}

\section{Hyperbolic drift: the silver envelope}\label{sec:drift}

\subsection{The hyperbolic embedding}

Embed the seeds in the hyperbolic upper half-plane by $z(m,n)=(n+i)/m$, with base point $o=i$.
Then
\[
\cosh d\bigl(o,z(m,n)\bigr)=1+\frac{n^2+(m-1)^2}{2m},
\qquad
\log m\le d\bigl(o,z(m,n)\bigr)\le\log m+\log2 \quad (0<n<m),
\]
so hyperbolic distance is the logarithm of the first Euclid coordinate to within $\log2$.

The growth of $m$ is governed by the \emph{silver potential} $\Phi(m,n)=m+(\sqrt2-1)n$. Direct
computation gives
\[
\Phi(L(m,n))=(1+\sqrt2)m-n,\quad
\Phi(M(m,n))=(1+\sqrt2)m+n,\quad
\Phi(R(m,n))=m+(1+\sqrt2)n,
\]
whereas $(1+\sqrt2)\Phi(m,n)=(1+\sqrt2)m+n$. Hence $\Phi(a\cdot v)\le(1+\sqrt2)\Phi(v)$ for
each move, \emph{with equality precisely for $M$} (the case $R$ uses $n<m$). Iterating gives
$\Phi\le(1+\sqrt2)^{k+1}$ at depth $k$ and therefore the sharp envelope, in terms of the
labelling word $w$,
\begin{equation}\label{eq:envelope}
\bigl(\#M(w)+1\bigr)\log2\;\le\;d\bigl(o,z(\mathrm{run}(w))\bigr)\;\le\;
\bigl(|w|+1\bigr)\log(1+\sqrt2)+\log2 .
\end{equation}
The upper bound is optimal, attained along the pure-$M$ (Pell) spine.

\subsection{Drift in mean and almost surely}

\begin{lemma}[Expected number of middle moves]\label{lem:countM}
In a random Berggren word of length $n$ the mean number of middle moves is exactly $np_1$.
\end{lemma}

\begin{theorem}[Drift sandwich]\label{thm:drift}
Let $z_n$ be the node reached after $n$ steps. Then
\[
(np_1+1)\log2\;\le\;\E\,d(o,z_n)\;\le\;(n+1)\log(1+\sqrt2)+\log2,
\]
hence for $n\ge1$
\[
p_1\log2\;\le\;\frac{\E\,d(o,z_n)}{n}\;\le\;\log(1+\sqrt2)+\frac{\log(1+\sqrt2)+\log2}{n}.
\]
In particular every Berggren walk has strictly positive escape speed, and the silver exponent
$\log(1+\sqrt2)=0.88137\ldots$ bounds the speed of every Berggren walk.
\end{theorem}

\begin{proof}
Take expectations in \eqref{eq:envelope} and apply Lemma~\ref{lem:countM}; the right-hand side
of \eqref{eq:envelope} is deterministic.
\end{proof}

\begin{theorem}[Almost sure drift sandwich]\label{thm:aedrift}
For $\Ber(P)$-a.e.\ ray $x$ and every $\varepsilon>0$, for all large $n$,
\[
p_1\log2-\varepsilon\;\le\;\frac{d(o,z_n(x))}{n}\;\le\;\log(1+\sqrt2)+\varepsilon .
\]
\end{theorem}

\begin{proof}
Divide \eqref{eq:envelope} by $n$. By Theorem~\ref{thm:slln} with $g=\mathbf 1_{\{M\}}$ the
frequency of middle moves converges to $p_1$, giving the lower bound; the upper bound's excess
over $\log(1+\sqrt2)$ is $(\log(1+\sqrt2)+\log2)/n\to0$.
\end{proof}

\begin{corollary}[Almost sure escape to infinity]
For every weight vector, $d(o,z_n)\to+\infty$ almost surely; the harmonic measure is genuinely
carried by the boundary at infinity, not by the tree.
\end{corollary}

\begin{proof}
Eventually the frequency of middle moves exceeds $p_1/2>0$, so
$d(o,z_n)\ge n\frac{p_1}{2}\log2\to\infty$.
\end{proof}

\section{Two negative results}

\subsection{The spectral gap is $1$}

\begin{definition}[Transfer operator]
For $f:\bdry\to\R$ put
$(\Lop f)(x)=\sum_{a\in\A}p_af(\cons_ax)=p_0f(Lx)+p_1f(Mx)+p_2f(Rx)$.
This is the Markov operator of the walk; its fixed points are the harmonic functions and its
invariant measure is $\Ber(P)$. Say $f$ \emph{depends on the first $n$ letters} if $f(x)=f(y)$
whenever $x_i=y_i$ for $i<n$; the union of these spaces is the space of locally constant
observables, dense in $C(\bdry)$ and in $L^2(\Ber(P))$.
\end{definition}

\begin{lemma}[One letter of memory lost per application]\label{lem:memory}
If $f$ depends on the first $n+1$ letters, then $\Lop f$ depends on the first $n$.
\end{lemma}

\begin{proof}
If $x_i=y_i$ for $i<n$, then $\cons_ax$ and $\cons_ay$ agree in their first $n+1$ coordinates
for each $a$, so the summands agree.
\end{proof}

\begin{theorem}[Nilpotency modulo constants]\label{thm:nilpotent}
If $f$ depends on the first $n$ letters, then $\Lop^n f$ is constant. Consequently:
(i) the only eigenvalues of $\Lop$ on locally constant observables are $0$ and $1$;
(ii) the eigenspace of $1$ consists exactly of the constants;
(iii) the spectral gap is $1$, independently of $(p_0,p_1,p_2)$;
(iv) in particular $\log(1+\sqrt2)=0.88137\ldots\in(0,1)$ is \emph{not} an eigenvalue of
$\Lop$.
\end{theorem}

\begin{proof}
Iterating Lemma~\ref{lem:memory} $n$ times sends dependence on the first $n$ letters to
dependence on none, i.e.\ constancy. If $\Lop f=\lambda f$ with $f\ne0$ depending on the first
$n$ letters, then $\lambda^nf=\Lop^nf$ is a constant $c$; if $\lambda\notin\{0,1\}$ then $f$ is
the constant $c\lambda^{-n}$, and since $\Lop$ fixes constants, $\lambda c\lambda^{-n}=
c\lambda^{-n}$, forcing $c=0$ and $f\equiv0$, a contradiction. If $\Lop f=f$ then
$f=\Lop^nf$ is constant.
\end{proof}

This refutes the conjecture that the second eigenvalue of the Berggren Markov operator is
governed by the silver ratio: the situation is the extreme opposite of a small gap. Silver
governs the drift (Theorems~\ref{thm:drift} and \ref{thm:aedrift}), not the spectrum.

\subsection{The entropy--metric gap}

The tree carries two exponents. The \emph{combinatorial} one is $\log3$: each node has three
children, and the entropy of any harmonic measure is at most $\log3$
(Proposition~\ref{prop:gibbs}). The \emph{metric} one is read off the hyperbolic embedding: a
depth-$n$ node sits at distance at most $2(n+1)\log(1+\sqrt2)+O(1)$ in the log-hypotenuse
normalisation, so the natural conformal exponent is $2\log(1+\sqrt2)$.

\begin{lemma}
$(1+\sqrt2)^2=3+2\sqrt2$, hence $2\log(1+\sqrt2)=\log(3+2\sqrt2)$.
\end{lemma}

\begin{theorem}[The two exponents never coincide]\label{thm:gap}
$\log3<2\log(1+\sqrt2)$. Numerically $1.09861\ldots<1.76275\ldots$
\end{theorem}

\begin{definition}
The hyperbolic dimension of the harmonic measure is
$\dim_{\mathrm{hyp}}\nu_P=H(P)/\bigl(2\log(1+\sqrt2)\bigr)$.
\end{definition}

\begin{theorem}[Uniform dimension gap]\label{thm:hypdim}
For every weight vector $P$,
\[
\dim_{\mathrm{hyp}}\nu_P\;\le\;\frac{\log3}{2\log(1+\sqrt2)}\;=\;0.62321\ldots\;<\;1,
\]
with equality on the left exactly for the fair walk; the deficit
$1-\log3/(2\log(1+\sqrt2))=0.37679\ldots$ is uniform in $P$. Moreover
$\dim_{\mathrm{hyp}}\nu_P\le2/3$, as a consequence of $3^3\le(1+\sqrt2)^4$.
\end{theorem}

\begin{proof}
Combine Proposition~\ref{prop:gibbs} with Theorem~\ref{thm:gap}. The explicit bound is
equivalent to $3\log3\le4\log(1+\sqrt2)$, i.e.\ $27\le(1+\sqrt2)^4=17+12\sqrt2=33.97\ldots$
\end{proof}

Thus the harmonic measure of a Berggren walk is never the conformal measure of the hyperbolic
embedding: the entropy generated per step ($\le\log3$) is strictly less than the hyperbolic
length generated per step ($2\log(1+\sqrt2)$), by a definite margin. The tree branches three
ways but stretches by $1+\sqrt2$, and three is not enough to catch up.

\section{Algorithms}

\paragraph{Word-to-triple evaluation.} Fold the three affine maps right to left from $(2,1)$
and apply Euclid's formulas: $O(n)$ arithmetic operations on integers of bit length
$\Theta(n)$.

\paragraph{Harmonic mass and surprisal.} The mass of the node labelled by $w$ is
$\prod_ip_{w_i}$ and its surprisal is $\sum_i\iota(w_i)$, both $O(n)$. The identity of
Theorem~\ref{thm:exact} can be checked by brute-force enumeration in $O(n3^n)$ or evaluated
in $O(1)$ as $nH(P)$; their agreement is a strong test of an implementation.

\paragraph{Estimation from a single ray.} Ray rigidity (Theorem~\ref{thm:rigid}) is directly
algorithmic: count letters along one trajectory and normalise. By
Theorem~\ref{thm:chernoff} the error is $O(\sqrt{\log(1/\delta)/n})$ with probability
$1-\delta$, at exact exponential rate $\KL(u\Vert p_a)$; Theorem~\ref{thm:bhatt} shows this is
essentially optimal among all depth-$n$ procedures.

\section{Discussion}

\begin{center}
\begin{tabular}{ll}
\toprule
Object & Value \\
\midrule
Boundary & Cantor set $\{L,M,R\}^{\N}$, 3-adic topology \\
Harmonic measure & Unique; equals $\Ber(p_0,p_1,p_2)$ \\
Entropy & $H(P)$ exactly, at every finite depth and a.s. \\
Dimension (3-adic) & $H(P)/\log3\in(0,1]$; $=1$ iff fair \\
Dimension (hyperbolic) & $H(P)/(2\log(1+\sqrt2))\le0.6232\ldots\le2/3$ \\
Shift & Ergodic for every $P$; measures pairwise singular \\
Drift & $p_1\log2\le\text{speed}\le\log(1+\sqrt2)$, in mean and a.s. \\
Spectral gap & $1$, for every $P$ \\
Separation rate & Between the Chernoff and Bhattacharyya exponents \\
\bottomrule
\end{tabular}
\end{center}

\paragraph{Three constants, three roles.} The tree's natural constants do not collapse into
one. $\log3$ is the \emph{information} exponent; $\log(1+\sqrt2)$ is the \emph{metric}
exponent, attained on the Pell spine of pure middle moves; and $1$ is the \emph{spectral gap},
maximal and insensitive to the weights.

\paragraph{Comparison with free groups.} The Berggren tree is the Cayley graph of a free monoid
on three generators, so much of the theory is formally parallel to random walks on free
groups. What is special here is arithmetic: the boundary points are directions in the space of
primitive Pythagorean triples, and the metric comes from the hyperbolic embedding
$z(m,n)=(n+i)/m$, whose growth constant is $1+\sqrt2$ rather than the branching number. It is
exactly this mismatch that produces the uniform dimension deficit of Theorem~\ref{thm:hypdim},
which has no analogue in the homogeneous free-group setting.

\paragraph{Applications.} The harmonic measure gives a rigorous meaning to ``a random
Pythagorean triple'': sampling at depth $n$ with weights $P$ produces triples whose
log-hypotenuse concentrates in $[np_1\log2,\,n\log(1+\sqrt2)]$, with $H(P)/\log3$ controlling
how much of the tree is explored. Theorems~\ref{thm:sep} and \ref{thm:bhatt} give a complete
hypothesis-testing theory on this boundary, with matching upper and lower bounds on the
achievable error exponent. Finally, $\{\Ber(P)\}$ is a two-parameter family of pairwise
mutually singular measures with full support and prescribed dimension ranging over $(0,1]$ on
one compact set --- a clean testbed for multifractal formalism with arithmetic labels.

\section{Future directions}

\begin{conjecture}[Exact escape rate]
The limit $\lim_n\E\,d(o,z_n)/n$ exists and equals $\ell(P)=p_0\kappa_0+p_1\kappa_1+p_2\kappa_2$
for explicit move-dependent exponents $\kappa$, with $\kappa=(0,\,2\log(1+\sqrt2),\,0)$ in the
log-hypotenuse metric: the gap between the two sides of Theorem~\ref{thm:drift} closes, and
the middle move alone contributes to the speed.
\end{conjecture}

\begin{conjecture}[Hyperbolic dimension]
With an exact escape rate in hand, $\dim=H(P)/\ell(P)$ should replace the bound of
Theorem~\ref{thm:hypdim}, and should be maximised at a non-fair weight vector --- the walk
that optimally trades information against displacement.
\end{conjecture}

\begin{conjecture}[Sharp cutoff constant]
The true depth-$n$ separation exponent is the Chernoff information
$C(P,Q)=-\log\min_{0\le t\le1}\sum_ap_a^tq_a^{1-t}$, coinciding with the Bhattacharyya bound
exactly when the optimising $t$ is $1/2$.
\end{conjecture}

Further programmes: replacing the memoryless step law by a Markov chain on $\{L,M,R\}$, where
the harmonic measure should become a Gibbs rather than a product measure while ray rigidity
survives with the transition matrix as invariant; the multifractal spectrum of $\Ber(P)$ with
respect to the hypotenuse metric rather than the 3-adic one; the local behaviour of the
harmonic measure near distinguished rays such as the Pell spine, and the associated
Patterson--Sullivan theory of the hyperbolic embedding, which should explain the constant $2/3$
structurally rather than numerically.

\section{Conclusion}

The random walk on the Berggren tree of primitive Pythagorean triples has a complete and
completely explicit boundary theory: unique Bernoulli harmonic measure, exact entropy
$H(P)$ at every finite depth and almost surely, 3-adic dimension $H(P)/\log3$ maximal exactly
for the fair walk, an ergodic boundary shift, rigid and exponentially quantified separation of
distinct walks with matching Chernoff and Bhattacharyya exponents, and almost sure escape to
infinity at a speed sandwiched between $p_1\log2$ and $\log(1+\sqrt2)$. Two conjectures fell:
the silver ratio does not govern the spectral gap, which is $1$ for every weight vector; and
silver outruns entropy, $\log3<2\log(1+\sqrt2)$, so the hyperbolic dimension of the harmonic
measure is at most $2/3$ uniformly.

\end{document}

