function EVAL(word w over {L, M, R}):
    (m, n) <- (2, 1)                        # the seed of (3, 4, 5)
    for a in reverse(w):
        if a = L: (m, n) <- (2m - n, m)
        if a = M: (m, n) <- (2m + n, m)
        if a = R: (m, n) <- (m + 2n, n)
    return (m, n)

function TRIPLE(w):
    (m, n) <- EVAL(w)
    return (m^2 - n^2, 2*m*n, m^2 + n^2)

function HARMONIC_MASS(w, (p_L, p_M, p_R)):
    mass <- 1
    for a in w: mass <- mass * p_a
    return mass

function VERIFY_BERGGREN(D):
    seen <- empty map from triples to words
    for d = 0 .. D:
        for each word w of length d:
            t <- TRIPLE(w)
            assert t is a primitive Pythagorean triple
            assert t not in seen                # injectivity
            seen[t] <- w
    return |seen|

