function SHANNON(p):
    return - sum over a of p_a * log(p_a)

function LEVEL_ENTROPY_BRUTEFORCE(p, n):        # cost O(n 3^n)
    total <- 0
    for each word w in {L, M, R}^n:
        mass <- 1 ; surp <- 0
        for a in w: mass <- mass * p_a ; surp <- surp - log(p_a)
        total <- total + mass * surp
    return total

function LEVEL_ENTROPY_EXACT(p, n):             # cost O(1)
    return n * SHANNON(p)
    # justification: exchange the sums; for each fixed position i the
    # remaining coordinates sum to 1, leaving sum_a p_a (-log p_a)

function SMB_ALONG_RAY(p, N):                   # cost O(N)
    running <- 0
    for i = 1 .. N:
        a <- sample a letter with probabilities p
        running <- running - log(p_a)
        report (i, running / i)                 # -> H(p) almost surely

function KL(u, s):
    return u*log(u/s) + (1-u)*log((1-u)/(1-s))

function BHATTACHARYYA(P, Q):
    return sum over a of sqrt(p_a * q_a)

function SEPARATION_BRACKET(P, Q):
    a <- argmax over letters of |p_a - q_a|
    if |p_a - q_a| = 0: return 'walks identical'

    # achievability: optimise the threshold u between p_a and q_a
    (lo, hi) <- (min(p_a, q_a), max(p_a, q_a))
    maximise f(u) = min(KL(u || p_a), KL(u || q_a)) on (lo, hi)
        by golden-section search
    (u*, c) <- argmax and max value

    # converse: the Bhattacharyya speed limit
    beta <- BHATTACHARYYA(P, Q)
    converse <- -2 * log(beta)

    assert c <= true cutoff rate <= converse
    return (u*, c, beta, converse)

function PHI(m, n):  return m + (sqrt(2) - 1) * n
function HDIST(m, n): return arccosh(1 + (n^2 + (m-1)^2) / (2m))

function CERTIFY_POTENTIAL(D):
    worst <- {L: 0, M: 0, R: 0}
    for d = 0 .. D:
        for each word w of length d:
            v <- EVAL(w)
            for a in {L, M, R}:
                r <- PHI(a . v) / PHI(v)
                assert r <= 1 + sqrt(2)
                worst[a] <- max(worst[a], r)
    return worst          # worst[M] = 1 + sqrt(2) exactly

function CERTIFY_ENVELOPE(D):
    for every word w of length <= D:
        d <- HDIST(EVAL(w))
        assert (count of M in w + 1) * log 2 <= d
        assert d <= (|w| + 1) * log(1 + sqrt 2) + log 2

function MEASURE_DRIFT(p, depths, samples):
    for n in depths:
        total <- 0
        repeat samples times:
            w <- n letters sampled independently with probabilities p
            total <- total + HDIST(EVAL(w))
        mean <- total / samples / n
        assert p_M * log 2 <= mean
        assert mean <= log(1 + sqrt 2) + (log(1 + sqrt 2) + log 2)/n
        report (n, mean)
